CID='photo_poses';NEW_ENTRIES=[];GROUPS=[]
category(CID,'摄影摆姿与合影','48项镜头前摆姿，按自拍、镜面、半身、全身、坐姿、墙窗边、街拍、裙装、道具、氛围及双人三人合影浏览。图例标明半身或全身景别、机位高度、视线与支撑；半身图按标注景别取景，手与拍摄道具完整保留。',['R04','R09'])

def block(key,title,text,framing='full',actors=1):
    rows=[line.split('|') for line in text.strip().splitlines()];assert len(rows)==4
    GROUPS.append(dict(id=key,name=title,framing=framing,actors=actors))
    for i,(name,en,view,camera,gaze,support,desc,recipe) in enumerate(rows):
        half=framing=='half' or (framing=='mixed' and i<3)
        add(CID,title,f'{name}|{en}|{desc}。景别：'+('半身，取至大腿中段' if half else '全身')+f'；人物朝向：{view}；机位：{camera}；视线：{gaze}。')
        e=CATALOG[-1];e.update(added_in='55.0',photo_pose_reference=True,photo_pose_group=key,photo_scene=title,photo_framing='半身' if half else '全身',camera_height=camera,gaze_direction=gaze,
          pose_reference=True,pose_view=view,pose_support=support,pose_phase='拍摄定格',pose_focus=desc,pose_actors=actors,illustration_recipe=recipe,
          age_min=25,adult_only=True,minor_reference=False,aliases=['拍照','拍照姿势','拍照pose','摄影摆姿','pose','pos','写真',title],reference_ids=['R04','R09'],
          note='成年角色镜头前摆姿参考。结合景别、镜头高度、眼神和肩髋方向选择，再根据服装与场景调整手部位置；图为摆姿示意，不把特定体型或表情作为好看的唯一标准。')
        NEW_ENTRIES.append(e)

